<script setup lang="ts">
import type{ApiEnvelope,LinkRecord}from'~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});const route=useRoute();const period=ref('30d');interface Row{label:string;value:number}interface Analytics{period:string;total_clicks:number;unique_clicks:number;timeline:Array<{date:string;clicks:number;unique_clicks:number}>;referrers:Row[];countries:Row[];devices:Row[];browsers:Row[];operating_systems:Row[]}
const{data:link}=await useFetch<ApiEnvelope<LinkRecord>>(`/api/backend/links/${route.params.id}`);const{data,pending,error,refresh}=await useFetch<ApiEnvelope<Analytics>>(()=>`/api/backend/links/${route.params.id}/analytics`,{query:computed(()=>({period:period.value})),watch:[period]});useSeoPage('Link analytics','Click trends and audience aggregates for your link.',`/dashboard/links/${route.params.id}/analytics`)
</script>
<template><div class="dashboard-page"><NuxtLink :to="`/dashboard/links/${route.params.id}`" class="text-xs text-text-muted hover:text-brand">← Back to link</NuxtLink><div class="mt-4 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="page-title">{{ link?.data.title||link?.data.short_code||'Link analytics' }}</h1><p class="mt-1 text-sm text-text-secondary">{{ link?.data.short_url }}</p></div><div class="inline-flex self-start rounded-md border border-border bg-surface2 p-0.5"><button v-for="range in ['7d','30d','90d']" :key="range" class="rounded-sm px-3 py-1.5 text-xs font-medium" :class="period===range?'bg-surface shadow-xs':'text-text-muted'" @click="period=range">{{ range.toUpperCase() }}</button></div></div><LoadingState v-if="pending" class="mt-6"/><div v-else-if="error" class="surface mt-6 p-6"><p class="text-sm text-danger">Analytics could not be loaded.</p><button class="btn-secondary mt-3" @click="refresh()">Try again</button></div><template v-else-if="data"><div class="mt-6 grid grid-cols-2 gap-3"><StatCard label="Total clicks" :value="data.data.total_clicks.toLocaleString()"/><StatCard label="Unique visitors" :value="data.data.unique_clicks.toLocaleString()" tone="violet"/></div><div class="mt-5"><AnalyticsChart :points="data.data.timeline"/></div><div class="mt-5 grid gap-5 md:grid-cols-2 xl:grid-cols-3"><section v-for="section in [{title:'Referrers',rows:data.data.referrers},{title:'Countries',rows:data.data.countries},{title:'Devices',rows:data.data.devices},{title:'Browsers',rows:data.data.browsers},{title:'Operating systems',rows:data.data.operating_systems}]" :key="section.title" class="surface p-5"><h2 class="text-sm font-semibold">{{ section.title }}</h2><div v-if="section.rows.length" class="mt-4 grid gap-3"><div v-for="row in section.rows.slice(0,8)" :key="row.label" class="flex justify-between gap-4 text-xs"><span class="truncate text-text-secondary">{{ row.label }}</span><strong>{{ row.value.toLocaleString() }}</strong></div></div><p v-else class="mt-4 text-sm text-text-muted">No data in this range.</p></section></div></template></div></template>
